 info=page.evaluate('window.__connected.inspect()');assert info['foundation'] and info['bioSolid'];assert info['stairs']==96 and info['library']==2;assert abs(info['gateL']-info['gateR'])<1e-9;assert not info['roadPaintInsideArc'],info['roadPaintInsideArc'][:3]
