 assert not errors,errors;print(json.dumps({'result':'PASS','checks':['solid connection foundations','single primary-road facade','two-storey library','full stair descent/ascent in actual collision','cannot walk under basement','equal gate lanes','no markings inside irregular entrance','developer modal pauses movement and records real position','no JS errors'],'details':info},ensure_ascii=False));b.close()
